INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (9009,4,3,'수정 대상: div · 점심 특선 파스타 세트\n위치: body > div:nth-of-type(1) > div:nth-of-type(1)\n선택 코드:\n<div style=\"background:rgba(255,255,255,0.6);border-radius:20px;padding:16px 20px;margin-bottom:16px;box-shadow:0 4px 12px rgba(200,120,60,0.1)\">\n    <h1 data-slot=\"eventName\" style=\"margin:0;font-size:30px;font-weight:800;color:#C2622A;line-height:1.3\">점심 특선 파스타 세트</h1>\n  </div>\n수정 요청: 여기 글씨 좀만 작게\n선택한 부분 위주로 수정하고 다른 영역과 슬롯 구조는 유지해 주세요.','e2f76cf8-9931-40bc-9ba4-d8a291691306','<span data-slot=\"adLabel\">광고</span><div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:28px 24px;background:linear-gradient(160deg,#FFF8F0,#FFE8CC);font-family:sans-serif;text-align:center;border-radius:24px\">\n  \n  <div style=\"background:rgba(255,255,255,0.6);border-radius:20px;padding:16px 20px;margin-bottom:16px;box-shadow:0 4px 12px rgba(200,120,60,0.1)\">\n    <h1 data-slot=\"eventName\" style=\"margin:0;font-size:22px;font-weight:800;color:#C2622A;line-height:1.3\">점심 특선 파스타 세트</h1>\n  </div>\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:20px;background-color:#F5DEC8;box-shadow:0 6px 18px rgba(180,100,40,0.15);margin-bottom:16px\">\n  <div style=\"background:rgba(255,255,255,0.65);border-radius:16px;padding:18px 16px 12px;box-shadow:0 4px 12px rgba(200,120,60,0.08)\">\n    <strong data-slot=\"discount\" style=\"display:block;font-size:26px;font-weight:800;color:#D4622A;margin-bottom:10px\">전채와 메인 20% 할인</strong>\n    <span data-slot=\"period\" style=\"display:inline-block;background:linear-gradient(90deg,#F7C59F,#F4A96A);color:#7A3A18;font-size:14px;font-weight:600;padding:6px 20px;border-radius:999px;box-shadow:0 2px 8px rgba(200,100,40,0.15)\">월·화·수 11시~14시</span>\n  </div>\n</div>',NULL,'2026-10-17 12:57:16.776555','2026-10-17 12:57:16.776555',NULL);
INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (9012,9004,1,'따뜻하고 편안한 가정식 식당 느낌의 카드형 템플릿을 만들어줘. 색은 크림 배경 #FFF4E0, 진한 갈색 글자 #4A2C1A, 주황 포인트 #D9822B, 흰색 #FFFFFF만 써. 이벤트명 영역은 맨 위 왼쪽 정렬로 serif 굵게 32px, 그 아래에 갈색 점선 구분선을 하나 둬. 이미지 영역은 그 아래에 크게 두고 갈색 2px 테두리와 모서리 24px을 줘. 할인 내용 영역은 이미지 바로 아래에 주황 바탕 모서리 16px 상자 안에 흰색 굵게 34px로 넣어. 기간 영역은 맨 아래 가운데에 갈색 14px로 작게 둬. 여백은 넉넉하게.','89b09ffe-8b90-42d8-b17e-89c01c9d89bd','<span data-slot=\"adLabel\">광고</span><div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 28px;background:#FFF4E0;font-family:serif;border-radius:20px\">\n  <h1 data-slot=\"eventName\" style=\"margin:0 0 16px;font-size:32px;font-weight:800;color:#4A2C1A;text-align:left;line-height:1.3\">오늘의 가정식 한 상</h1>\n  <div style=\"width:100%;border-top:2px dashed #4A2C1A;margin-bottom:20px\"></div>\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:24px;border:2px solid #4A2C1A;background-color:#EDD9B8;box-shadow:0 4px 14px rgba(74,44,26,0.18)\">\n  <div data-slot=\"discount\" style=\"margin:20px 0 0;background:#D9822B;border-radius:16px;padding:16px 20px;text-align:center\">\n    <strong style=\"font-size:34px;font-weight:800;color:#FFFFFF;line-height:1.2\">된장찌개 정식 20% 할인</strong>\n  </div>\n  <p data-slot=\"period\" style=\"margin:16px 0 0;font-size:14px;color:#4A2C1A;text-align:center;font-family:sans-serif\">평일 오전 11시 ~ 오후 2시 · 쿠폰 지참 시 적용</p>\n</div>',NULL,'2026-10-20 13:08:21.911221','2026-10-20 13:08:21.911221',NULL);
