INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000037,20000004,3,'수정 대상: 이벤트명\n위치: [data-slot=\"eventName\"]\n선택 코드 187자:\n<h1 data-slot=\"eventName\" style=\"margin:0 0 20px;font-size:36px;font-weight:900;line-height:1.15;color:#E8F0EC;letter-spacing:-1px\">오늘의<br><span style=\"color:#7EC8A0\">셰프 추천</span> 런치</h1>\n수정 요청: 이거 멘트 바꿔줘\n선택한 부분 위주로 수정하고 다른 영역과 슬롯 구조는 유지해 주세요.','d27627c9-1884-45b8-ae27-3252bace6264','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 28px;background:linear-gradient(135deg,#0D1F1A 60%,#1A3A2A);color:#E8F0EC;font-family:serif;text-align:left;border-radius:20px\">\n\n  <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:20px\">\n    <div style=\"flex:1;height:1px;background:rgba(160,210,180,0.35)\"></div>\n    <span style=\"font-size:11px;letter-spacing:5px;color:#7EC8A0;font-weight:700;font-family:sans-serif\">LUNCH SPECIAL</span>\n    <div style=\"flex:1;height:1px;background:rgba(160,210,180,0.35)\"></div>\n  </div>\n\n  <h1 data-slot=\"eventName\" style=\"margin:0 0 20px;font-size:36px;font-weight:900;line-height:1.15;color:#E8F0EC;letter-spacing:-1px\">딱 하루,<br><span style=\"color:#7EC8A0\">지금만 누리는</span> 특별한 점심</h1>\n\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:12px;background-color:#1A3A2A;box-shadow:0 12px 40px rgba(0,0,0,0.55)\">\n\n  <div style=\"margin:22px 0 0;padding:4px 0 4px 20px;border-left:4px solid #7EC8A0\">\n    <p data-slot=\"discount\" style=\"margin:0 0 6px;font-size:28px;font-weight:900;color:#B6EDCC;line-height:1.1\">코스 전 메뉴<br>25% 할인</p>\n  </div>\n\n  <p data-slot=\"period\" style=\"margin:16px 0 0 0;font-size:13px;color:rgba(200,230,215,0.65);letter-spacing:3px;font-family:sans-serif;font-weight:600\">MON – FRI&nbsp;&nbsp;11:30 – 14:00</p>\n\n</div>','eventName 슬롯의 문구를 좀 더 직관적이고 식욕을 자극하는 예시 문구로 교체했습니다.','2026-10-23 15:45:24.783962','2026-10-23 15:45:24.783962',NULL);
