px;background-color:#FFF9E3;box-shadow:0 0 0 4px #fff,0 0 0 8px #FF0080,0 0 0 12px #FFE600,0 0 0 16px #00B0FF,0 12px 32px rgba(0,0,0,0.35)\">\n\n  <div style=\"margin:16px 0 10px;padding:12px 8px;background:linear-gradient(135deg,rgba(255,255,255,0.15),rgba(255,255,255,0.45),rgba(255,255,255,0.15));border-radius:18px;border:3px solid rgba(255,255,255,0.9);box-shadow:0 0 24px rgba(255,0,128,0.5),0 0 24px rgba(0,176,255,0.5),inset 0 0 16px rgba(255,255,255,0.3)\">\n    <p data-slot=\"discount\" style=\"margin:0;font-size:28px;font-weight:900;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,0.3)\">런치 세트 20% 할인</p>\n  </div>\n\n  <p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:8px 22px;font-size:15px;font-weight:800;color:#fff;background:linear-gradient(90deg,#FF0080,#D500F9,#00B0FF,#FF0080);border-radius:999px;box-shadow:0 0 16px rgba(255,0,128,0.7),0 0 16px rgba(213,0,249,0.7),0 0 0 3px rgba(255,255,255,0.8);letter-spacing:1px;text-shadow:0 0 8px rgba(0,0,0,0.3)\">🦭 평일 오전 11시 ~ 오후 2시 🦭</p>\n\n</div>','이모지 장식 span을 삭제하고 나머지 구조와 슬롯은 그대로 유지했습니다.','2026-10-23 16:18:03.962601','2026-10-23 16:18:03.962601','2026-10-23 16:18:58.996602');
INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000059,20000008,11,'수정 대상: 이벤트명\n위치: [data-slot=\"eventName\"]\n선택 코드 158자:\n<h2 data-slot=\"eventName\" style=\"margin:0;font-size:34px;font-weight:900;line-height:1.3;color:#fff;text-shadow:0 2px 4px rgba(0,0,0,0.3)\">🦭 점심 특선 세트 🦭</h2>\n수정 요청: 그라데이션 말고 좀더 무지개가 구분되게 할수있나\n선택한 부분 위주로 수정하고 다른 영역과 슬롯 구조는 유지해 주세요.','6fe8be81-0c35-4c08-a02a-7dd2f4e48e1b','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 24px;background:linear-gradient(135deg,#FF0080,#FF6A00,#FFE600,#00E676,#00B0FF,#D500F9,#FF0080);color:#fff;font-family:sans-serif;text-align:center;border-radius:24px;position:relative;box-shadow:0 0 0 6px #fff,0 0 0 10px #FF0080,0 0 0 14px #00B0FF,0 0 30px 4px rgba(255,0,128,0.5)\">\n\n  <div style=\"position:absolute;top:0;left:0;width:100%;height:14px;background:linear-gradient(90deg,#FF0080,#FF6A00,#FFE600,#00E676,#00B0FF,#D500F9,#FF0080);border-radius:24px 24px 0 0;box-shadow:0 2px 10px rgba(255,0,128,0.6)\"></div>\n  <div style=\"position:absolute;bottom:0;left:0;width:100%;height:14px;background:linear-gradient(90deg,#D500F9,#00B0FF,#00E676,#FFE600,#FF6A00,#FF0080,#D500F9);border-radius:0 0 24px 24px;box-shadow:0 -2px 10px rgba(0,176,255,0.6)\"></div>\n\n  <div style=\"margin:12px 0 12px;padding:6px 12px;background:linear-gradient(90deg,rgba(255,255,255,0.18),rgba(255,255,255,0.35),rgba(255,255,255,0.18));border-radius:16px;border:2px solid rgba(255,255,255,0.7);box-shadow:0 0 18px rgba(255,255,255,0.4),inset 0 0 12px rgba(255,255,255,0.2)\">\n    <h2 data-slot=\"eventName\" style=\"margin:0;font-size:34px;font-weight:900;line-height:1.3;text-shadow:0 2px 4px rgba(0,0,0,0.35)\">\n      <span style=\"color:#FF0080\">🦭</span><span style=\"color:#FF2200\"> 점</span><span style=\"color:#FF6A00\">심</span><span style=\"color:#FFB300\"> 특</span><span style=\"color:#FFE600\">선</span><span style=\"color:#00C853\"> 세</span><span style=\"color:#00B0FF\">트</span><span style=\"color:#D500F9\"> </span><span style=\"color:#FF0080\">🦭</span>\n    </h2>\n  </div>\n\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:20px;background-color:#FFF9E3;box-shadow:0 0 0 4px #fff,0 0 0 8px #FF0080,0 0 0 12px #FFE600,0 0 0 16px #00B0FF,0 12px 32px rgba(0,0,0,0.35)\">\n\n  <div style=\"margin:16px 0 10px;padding:12px 8px;background:linear-gradient(135deg,rgba(255,255,255,0.15),rgba(255,255,255,0.45),rgba(255,255,255,0.15));border-radius:18px;border:3px solid rgba(255,255,255,0.9);box-shadow:0 0 24px rgba(255,0,128,0.5),0 0 24px rgba(0,176,255,0.5),inset 0 0 16px rgba(255,255,255,0.3)\">\n    <p data-slot=\"discount\" style=\"margin:0;font-size:28px;font-weight:900;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,0.3)\">런치 세트 20% 할인</p>\n  </div>\n\n  <p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:8px 22px;font-size:15px;font-weight:800;color:#fff;background:linear-gradient(90deg,#FF0080,#D500F9,#00B0FF,#FF0080);border-radius:999px;box-shadow:0 0 16px rgba(255,0,128,0.7),0 0 16px rgba(213,0,249,0.7),0 0 0 3px rgba(255,255,255,0.8);letter-spacing:1px;text-shadow:0 0 8px rgba(0,0,0,0.3)\">🦭 평일 오전 11시 ~ 오후 2시 🦭</p>\n\n</div>','eventName 텍스트에 각 글자별로 무지개 색상이 구분되도록 span으로 감싸 색을 나눴습니다.','2026-10-23 16:18:40.556556','2026-10-23 16:18:40.556556','2026-10-23 16:18:58.996602');
INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000062,20000010,1,'만화 효과 같은게 있는 템플릿 넣고 싶어 집중선같은게 있는거야 한곳으로 모이는','148d1051-2274-4782-bcfb-b0aa1782114a','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:28px 24px;background:#FFF200;color:#1A1A1A;font-family:sans-serif;text-align:center;position:relative;border-radius:20px\">\n\n  <!-- 집중선 레이어 -->\n  <div style=\"position:absolute;inset:0;overflow:hidden;border-radius:20px;z-index:0\">\n    <div style=\"position:absolute;top:50%;left:50%;width:0;height:0;transform:translate(-50%,-50%);border-style:solid;border-width:0 3px 600px 3px;border-color:transparent transparent rgba(0,0,0,0.07) transparent;transform-origin:top center;transform:translate(-50%,-50%) rotate(0deg)\"></div>\n    <span style=\"position:absolute;top:0;left:0;width:100%;height:100%;background:repeating-conic-gradient(rgba(0,0,0,0.06) 0deg 4deg, transparent 4deg 9deg);display:block\"></span>\n  </div>\n\n  <!-- 중앙 흰 원형 후광 -->\n  <div style=\"position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:72%;aspect-ratio:1/1;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,0.92) 40%,rgba(255,255,0,0) 75%);z-index:1;pointer-events:none\"></div>\n\n  <!-- 콘텐츠 -->\n  <div style=\"position:relative;z-index:2;display:flex;flex-direction:column;flex:1;min-height:0;align-items:center;justify-content:space-between\">\n\n    <!-- 상단 배지 + 행사명 -->\n    <div style=\"display:flex;flex-direction:column;align-items:center;gap:10px;margin-top:4px\">\n      <span style=\"background:#E8000D;color:#FFF;font-size:13px;font-weight:800;letter-spacing:2px;padding:5px 18px;border-radius:999px;box-shadow:2px 2px 0 #7A0008\">LUNCH SPECIAL</span>\n      <h1 data-slot=\"eventName\" style=\"margin:0;font-size:33px;font-weight:900;line-height:1.2;color:#1A1A1A;text-shadow:3px 3px 0 rgba(0,0,0,0.12)\">점심 특선 한우 불고기</h1>\n    </div>\n\n    <!-- 이미지 -->\n    <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:90%;object-fit:cover;border-radius:16px;background-color:#F5DEB3;box-shadow:4px 6px 0 rgba(0,0,0,0.22);margin:16px 0;border:3px solid #1A1A1A\">\n\n    <!-- 할인 강조 -->\n    <div style=\"display:flex;flex-direction:column;align-items:center;gap:8px;margin-bottom:4px\">\n      <div style=\"background:#E8000D;border-radius:14px;padding:10px 28px;box-shadow:3px 3px 0 #7A0008;border:2px solid #1A1A1A\">\n        <p data-slot=\"discount\" style=\"margin:0;font-size:28px;font-weight:900;color:#FFF200;letter-spacing:-0.5px;text-shadow:2px 2px 0 rgba(0,0,0,0.3)\">불고기 세트 20% 할인!</p>\n      </div>\n      <p data-slot=\"period\" style=\"margin:0;font-size:14px;font-weight:700;color:#1A1A1A;background:rgba(255,255,255,0.75);padding:5px 18px;border-radius:999px;border:1.5px solid #1A1A1A\">평일 오전 11시 ~ 오후 2시</p>\n    </div>\n\n  </div>\n</div>','집중선(방사형 선)을 배경에 깔고, 만화 스타일의 강렬한 색감으로 만든 템플릿입니다.','2026-10-23 16:27:46.730054','2026-10-23 16:27:46.730054','2026-10-23 16:32:12.249564');
