INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000072,20000011,1,'우리 식당은 전세계의 산해진미를 고급지게 풀어낸 고급 레스토랑이야. 코스 요리를 주문하면 아시아, 아프리카, 유럽, 북아메리카, 남아메리카, 오세아니아의 대표 음식을 모두 골고루 맛볼 수 있어.\n우리 가게의 특징은 고급진 양복을 입은 웨이터가 서빙해줘.\n흰색과 빨간색을 써서 우리의 고급진 레스토랑에 어울리는 포스터를 만들어줘.','a58c9bb2-aeaf-4ed0-9e65-1b29e7272113','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 28px;background:linear-gradient(170deg,#ffffff,#fff0f0);color:#1a0000;font-family:serif;text-align:center;border-radius:20px\">\n\n  <div style=\"border:2px solid #C0002A;border-radius:16px;padding:10px 0 6px;margin-bottom:18px\">\n    <span style=\"font-size:11px;letter-spacing:4px;color:#C0002A;font-weight:700\">FINE DINING · WORLD CUISINE</span>\n  </div>\n\n  <h1 data-slot=\"eventName\" style=\"margin:0 0 18px;font-size:33px;font-weight:900;line-height:1.3;color:#8B0020;letter-spacing:1px\">세계 6대륙 코스 요리</h1>\n\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:14px;background-color:#f5d5da;box-shadow:0 8px 24px rgba(140,0,32,0.18)\">\n\n  <div style=\"margin:20px 0 0;background:linear-gradient(135deg,#C0002A,#8B0020);border-radius:14px;padding:18px 16px 14px\">\n    <p data-slot=\"discount\" style=\"margin:0 0 10px;font-size:26px;font-weight:900;color:#ffffff;letter-spacing:0.5px\">런치 코스 20% 할인</p>\n    <p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:5px 18px;font-size:14px;color:#ffe0e6;background:rgba(255,255,255,0.15);border-radius:999px;letter-spacing:1px\">평일 11:30 ~ 14:00</p>\n  </div>\n\n</div>','흰색과 빨간색을 중심으로 고급스러운 분위기의 레스토랑 포스터 템플릿을 만들었습니다.','2026-10-23 16:29:56.907297','2026-10-23 16:29:56.907297','2026-10-23 16:36:39.390968');
