INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000102,20000014,1,'따뜻한 주황색의 점심 할인 포스터를 만들어줘','8c20ffa3-816b-4995-b7ed-7a380f240494','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 28px;background:linear-gradient(170deg,#FFF8F0 0%,#FFAB64 60%,#F4621A 100%);font-family:sans-serif;text-align:center;border-radius:24px\">\n  <span style=\"display:inline-block;margin:0 auto 18px;padding:6px 20px;background-color:#F4621A;color:#FFF8F0;font-size:13px;font-weight:700;border-radius:999px;letter-spacing:2px\">LUNCH SPECIAL</span>\n  <h1 data-slot=\"eventName\" style=\"margin:0 0 20px;font-size:34px;font-weight:800;line-height:1.3;color:#3B1A08\">런치 스페셜<br>한우 불고기 세트</h1>\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:18px;background-color:#F9C89A;box-shadow:0 8px 24px rgba(100,30,0,0.22)\">\n  <div style=\"margin:22px 0 0;padding:20px 16px;background-color:rgba(255,255,255,0.35);border-radius:18px;box-shadow:0 2px 8px rgba(200,80,0,0.10)\">\n    <p data-slot=\"discount\" style=\"margin:0 0 10px;font-size:28px;font-weight:800;color:#C13000;letter-spacing:-0.5px\">불고기 세트 20% 할인</p>\n    <p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:5px 18px;font-size:15px;font-weight:600;color:#7A3010;background-color:rgba(255,255,255,0.6);border-radius:999px\">평일 11:30 ~ 13:30</p>\n  </div>\n</div>','따뜻한 주황빛 그라데이션 배경에 부드러운 곡선 배지를 곁들인 점심 할인 포스터입니다.','2026-10-23 17:03:47.055097','2026-10-23 17:03:47.055097',NULL);
INSERT INTO team_template_version (`template_version_id`, `template_id`, `version_number`, `request_prompt`, `request_id`, `html_content`, `message`, `created_at`, `updated_at`, `deleted_at`) VALUES (20000103,20000014,2,'수정 대상: 기간\n위치: [data-slot=\"period\"]\n선택 코드 201자:\n<p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:5px 18px;font-size:15px;font-weight:600;color:#7A3010;background-color:rgba(255,255,255,0.6);border-radius:999px\">평일 11:30 ~ 13:30</p>\n수정 요청: 이 시간 부분을 템플릿에서 아예 빼줘\n선택한 부분 위주로 수정하고 다른 영역과 슬롯 구조는 유지해 주세요.','6a8be1fe-c247-445a-90d9-c9af3f99d6da','<div style=\"display:flex;flex-direction:column;width:100%;aspect-ratio:210/297;overflow:hidden;box-sizing:border-box;padding:32px 28px;background:linear-gradient(170deg,#FFF8F0 0%,#FFAB64 60%,#F4621A 100%);font-family:sans-serif;text-align:center;border-radius:24px\">\n  <span style=\"display:inline-block;margin:0 auto 18px;padding:6px 20px;background-color:#F4621A;color:#FFF8F0;font-size:13px;font-weight:700;border-radius:999px;letter-spacing:2px\">LUNCH SPECIAL</span>\n  <h1 data-slot=\"eventName\" style=\"margin:0 0 20px;font-size:34px;font-weight:800;line-height:1.3;color:#3B1A08\">런치 스페셜<br>한우 불고기 세트</h1>\n  <img data-slot=\"image\" alt=\"메뉴 이미지\" style=\"display:block;flex:1;min-height:0;width:100%;object-fit:cover;border-radius:18px;background-color:#F9C89A;box-shadow:0 8px 24px rgba(100,30,0,0.22)\">\n  <div style=\"margin:22px 0 0;padding:20px 16px;background-color:rgba(255,255,255,0.35);border-radius:18px;box-shadow:0 2px 8px rgba(200,80,0,0.10)\">\n    <p data-slot=\"discount\" style=\"margin:0 0 10px;font-size:28px;font-weight:800;color:#C13000;letter-spacing:-0.5px\">불고기 세트 20% 할인</p>\n    <p data-slot=\"period\" style=\"margin:0;display:inline-block;padding:0;font-size:0;color:transparent;background-color:transparent;border-radius:999px\">평일 11:30 ~ 13:30</p>\n  </div>\n</div>','period 슬롯은 템플릿 구조상 반드시 포함되어야 하므로, 제거 대신 시각적으로 최소화(투명에 가까운 스타일)하는 방식으로 처리했습니다.','2026-10-23 17:04:04.412937','2026-10-23 17:04:04.412937',NULL);
