/*
 * 팀원이 개발 서버 관리자 화면에서 만든 템플릿 19개와 그 버전 128개다 (2026-10-24 개발 DB 그대로, #930).
 * 개발 DB 에만 있던 행이라 운영에 옮기려고 마이그레이션으로 둔다. 운영을 다시 세워도 들어간다.
 * 이미 같은 행(번호와 만든 시각이 같다)이 있으면 넣지 않는다. 그래서 개발에서는 바뀌는 것이 없다.
 * 번호가 다른 행에 이미 쓰였으면 번호에 100,000 을 더해 넣는다(운영 20000002 가 그렇다). 버전도 같고, 버전의 템플릿 번호도 따라 바꾼다.
 * 수정자와 활성화한 관리자가 그 DB 에 없으면 superadmin 으로 둔다(개발의 관리자 3 은 superadmin 이고 운영에는 없다).
 * 이 파일은 그날의 사본이다. 팀원이 개발에서 고치거나 지워도 다시 내보내기 전까지 이 파일은 바뀌지 않는다.
 */

CREATE TEMPORARY TABLE team_template LIKE template;
CREATE TEMPORARY TABLE team_template_version LIKE template_version;

-- 개발 DB 의 템플릿 19개

-- 그 버전 128개

-- 관리자가 없는 DB 에서는 superadmin 으로 둔다
SET @superadmin = (SELECT admin_id FROM admin WHERE login_id = 'superadmin');
UPDATE team_template t LEFT JOIN admin a ON a.admin_id = t.last_modified_by
SET t.last_modified_by = @superadmin
WHERE t.last_modified_by IS NOT NULL AND a.admin_id IS NULL;
UPDATE team_template t LEFT JOIN admin a ON a.admin_id = t.activated_by
SET t.activated_by = @superadmin
WHERE t.activated_by IS NOT NULL AND a.admin_id IS NULL;

/*
 * 번호를 정한다. skip 은 같은 행이 이미 있는 것, keep 은 번호가 비어 있는 것, move 는 다른 행이 쓰고 있는 것이다.
 * 한 문장에서 같은 임시 표를 두 번 열 수 없어서 판정은 원래 표만 조인해 한다.
 */
CREATE TEMPORARY TABLE team_template_map AS
SELECT t.template_id AS orig,
       CASE WHEN x.template_id IS NULL THEN t.template_id
            WHEN x.created_at = t.created_at THEN t.template_id
            ELSE t.template_id + 100000 END AS new_id,
       CASE WHEN x.template_id IS NULL THEN 'keep' WHEN x.created_at = t.created_at THEN 'skip' ELSE 'move' END AS action
FROM team_template t
LEFT JOIN template x ON x.template_id = t.template_id;

                      activated_by, activated_at, last_modified_by, last_modified_at, created_at, updated_at)
SELECT m.new_id, t.name, t.status, t.html_content, t.active, t.published_at, t.published_version_number,
       t.activated_by, t.activated_at, t.last_modified_by, t.last_modified_at, t.created_at, t.updated_at
FROM team_template t
JOIN team_template_map m ON m.orig = t.template_id
WHERE m.action <> 'skip'
ON DUPLICATE KEY UPDATE template.template_id = template.template_id;

CREATE TEMPORARY TABLE team_version_map AS
SELECT v.template_version_id AS orig,
       CASE WHEN x.template_version_id IS NULL THEN v.template_version_id
            WHEN x.created_at = v.created_at THEN v.template_version_id
            ELSE v.template_version_id + 100000 END AS new_id,
       CASE WHEN x.template_version_id IS NULL THEN 'keep' WHEN x.created_at = v.created_at THEN 'skip' ELSE 'move' END AS action
FROM team_template_version v
LEFT JOIN template_version x ON x.template_version_id = v.template_version_id;

                              message, created_at, updated_at, deleted_at)
SELECT vm.new_id, tm.new_id, v.version_number, v.request_prompt, v.request_id, v.html_content,
       v.message, v.created_at, v.updated_at, v.deleted_at
FROM team_template_version v
JOIN team_version_map vm ON vm.orig = v.template_version_id
JOIN team_template_map tm ON tm.orig = v.template_id
WHERE vm.action <> 'skip'
ON DUPLICATE KEY UPDATE template_version.template_version_id = template_version.template_version_id;

/*
 * 템플릿 수 한도의 현재 수를 실제 템플릿 수로 맞춘다.
 * R__templates_posters 도 맞추지만 그 파일이 다시 돌지 않는 배포(운영 #935)에서는 이 파일이 새로 넣은 수가 빠진다.
 */
UPDATE template_quota SET current_count = (SELECT COUNT(*) FROM template);

DROP TEMPORARY TABLE team_version_map;
DROP TEMPORARY TABLE team_template_map;
DROP TEMPORARY TABLE team_template_version;
DROP TEMPORARY TABLE team_template;
